import java.util.*;

class Solution {
    public int longestBalancedSubstring(String s) {
        Map<String, Integer> seen = new HashMap<>();
        seen.put("0,0", -1);
        int ca = 0, cb = 0, cc = 0;
        int maxLen = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == 'a') ca++;
            else if (ch == 'b') cb++;
            else if (ch == 'c') cc++;
            String key = (cb - ca) + "," + (cc - ca);
            if (seen.containsKey(key)) {
                maxLen = Math.max(maxLen, i - seen.get(key));
            } else {
                seen.put(key, i);
            }
        }
        return maxLen;
    }
}

var longestBalancedSubstring = function(s) {
    const seen = new Map();
    seen.set("0,0", -1);
    let ca = 0, cb = 0, cc = 0;
    let maxLen = 0;
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (ch === 'a') ca++;
        else if (ch === 'b') cb++;
        else if (ch === 'c') cc++;
        const key = `${cb - ca},${cc - ca}`;
        if (seen.has(key)) {
            maxLen = Math.max(maxLen, i - seen.get(key));
        } else {
            seen.set(key, i);
        }
    }
    return maxLen;
};
